import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, SimpleChanges } from '@angular/core';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'avtr',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule],
  templateUrl: './avatar.component.html',
  styleUrl: './avatar.component.scss'
})
export class AvatarComponent {
  @Input() size: string = 'lg';
  @Input() detail: {
    nUserid?: string,
    cEmail?: string,
    cFname?: string,
    cLname?: string,
    cProfile?: string,
    isAdmin?: boolean
  };

  @Input() active: boolean = false;
  initials: any = {};
  imgPath: string = `${environment.documentStorage}${environment.userProfilePath}`;
  @Input() path: string;
  @Input() sourcePath: string;
  constructor(private cf: CommonfunctionService, private cdr: ChangeDetectorRef) { }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['detail'] && changes['detail'].currentValue) {
      if (this.detail?.cProfile) {
        this.path = this.imgPath + (this.sourcePath || 'users/') + this.detail?.cProfile;
      }
      this.cf.get_userinit(this.detail).then((initials) => {
        this.initials = initials;
        this.cdr.markForCheck();  // Mark this component for check
      });
    }
    if (this.detail?.cProfile) {
      this.path = this.imgPath + (this.sourcePath || 'users/') + this.detail?.cProfile;
    }
    this.cdr.detectChanges();
  }

  ngOnInit(): void {
    this.path = this.imgPath + (this.sourcePath || 'users/') + this.detail?.cProfile;
    // console.log(this.path)
    this.cdr.detectChanges();
  }


  onPathError(detail) {
    // console.log('EROR')
    this.path = 'assets/colorlogo.svg'
    this.cdr.detectChanges();
  }


}
